SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='c30510f5-b27a-5296-8749-c248c4d4724a'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('e46996cd-052e-5b08-a966-f7e80129eccc','0026c547-3be7-529b-a380-19d2e2712b32')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='c30510f5-b27a-5296-8749-c248c4d4724a'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='c30510f5-b27a-5296-8749-c248c4d4724a'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('e46996cd-052e-5b08-a966-f7e80129eccc','0026c547-3be7-529b-a380-19d2e2712b32')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='c30510f5-b27a-5296-8749-c248c4d4724a'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='e46996cd-052e-5b08-a966-f7e80129eccc' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-worker-source-customer' AND q.fingerprint='f34efd94602f54843149268de669019090fcd31cde1deae687b4e76216458c24'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"worker-source-customer","status":"ok","value":{"customerProfileId":"c30510f5-b27a-5296-8749-c248c4d4724a","userId":"4b860286-670b-5db0-b416-d44c384f936b","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"e46996cd-052e-5b08-a966-f7e80129eccc","semanticKey":"customer-controls-worker-source-customer","fingerprint":"f34efd94602f54843149268de669019090fcd31cde1deae687b4e76216458c24","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='4439fb47-6ca9-57ae-973b-36dec7ca2ffd' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='ea075141-f54f-5724-9bf1-1b7db068a384' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"c30510f5-b27a-5296-8749-c248c4d4724a"},"prior":null,"committed":{"id":"c30510f5-b27a-5296-8749-c248c4d4724a","userId":"4b860286-670b-5db0-b416-d44c384f936b","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='c30510f5-b27a-5296-8749-c248c4d4724a' AND c.user_id='4b860286-670b-5db0-b416-d44c384f936b' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='worker-source-customer' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='a80b3873-08b1-58dd-9fa8-4b7554b188b3' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"c30510f5-b27a-5296-8749-c248c4d4724a","userId":"4b860286-670b-5db0-b416-d44c384f936b","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='add755d4-036e-5130-83f0-6ff538c68cc1' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"4b860286-670b-5db0-b416-d44c384f936b","track":"customer","customerProfileId":"c30510f5-b27a-5296-8749-c248c4d4724a","sourceCreationRevision":"0","sourceCreationReceipt":"e46996cd-052e-5b08-a966-f7e80129eccc","semanticKey":"customer_buyer_profile/c30510f5-b27a-5296-8749-c248c4d4724a/default-free-enrollment/v1"}'::jsonb)))=2));
